@Test
public void testBinaryEquals() {
    Expr expr1 = new BinaryOperator(ExprType.Plus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    Expr expr2 = new BinaryOperator(ExprType.Plus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    assertEquals(expr1, expr2);
    Expr expr3 = new BinaryOperator(ExprType.Minus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr3));
    Expr expr4 = new BinaryOperator(ExprType.Plus, new LiteralExpr("2", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr4));
    Expr expr5 = new BinaryOperator(ExprType.Plus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("3", LiteralType.Unsigned_Integer));
    assertFalse(expr1.equals(expr5));
}

@Test
public void testBinaryHierarchyEquals() {
    Expr left1 = new BinaryOperator(ExprType.Plus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    Expr right1 = new BinaryOperator(ExprType.Multiply, new LiteralExpr("2", LiteralType.Unsigned_Integer), new LiteralExpr("3", LiteralType.Unsigned_Integer));
    Expr one = new BinaryOperator(ExprType.Plus, left1, right1);
    Expr left2 = new BinaryOperator(ExprType.Plus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    Expr right2 = new BinaryOperator(ExprType.Multiply, new LiteralExpr("2", LiteralType.Unsigned_Integer), new LiteralExpr("3", LiteralType.Unsigned_Integer));
    Expr two = new BinaryOperator(ExprType.Plus, left2, right2);
    assertEquals(one, two);
    Expr left3 = new BinaryOperator(ExprType.Minus, new LiteralExpr("1", LiteralType.Unsigned_Integer), new LiteralExpr("2", LiteralType.Unsigned_Integer));
    Expr wrong1 = new BinaryOperator(ExprType.Plus, left3, right1);
    assertFalse(one.equals(wrong1));
}

