    assertEquals(1, group2.getStat(StatType.TABLE_NUM_BLOCKS).getValue());
    StatSet group3 = (StatSet) group.clone();
    assertEquals(2, group3.getAllStats().size());
    assertEquals(stat, group3.getStat(StatType.TABLE_NUM_ROWS));
