    assertEquals(NQLParser.LIKE, cond1.getChild(0).getType());
    assertEquals(NQLParser.EQUAL, cond2.getChild(0).getType());
    assertEquals(NQLParser.DIGIT, elseStmt.getChild(0).getType());
}

