    sortKeys[1] = new SortSpec(schema.getColumn("double"), true, false);
    Schema keySchema = new Schema();
    keySchema.addColumn(new Column("long", DataType.LONG));
    keySchema.addColumn(new Column("double", DataType.DOUBLE));
